use vstd::prelude::*;

verus! {

spec fn count_eligible(participations: Seq<int>, k: int) -> int
    requires
        k >= 0 && k <= 5,
        forall|i: int| 0 <= i && i < participations.len() as int ==> (participations.index(i) >= 0 && participations.index(i) <= 5),
    decreases participations.len()
{
    if participations.len() == 0 {
        0
    } else {
        let head = participations.index(0);
        let tail = participations.slice(1, participations.len());
        let count_tail = count_eligible(tail, k);
        if 5 - head >= k {
            count_tail + 1
        } else {
            count_tail
        }
    }
}

fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8
    requires
        k <= 5,
        forall|i: int| 0 <= i && i < participations@.len() as int ==> participations@.index(i) <= 5,
    ensures
        let eligible := count_eligible(participations@.slice(0, std::cmp::min(n as int, participations@.len() as int)), k as int);
        (result as int) == eligible / 3
{
    let mut count: u8 = 0;
    let limit = core::cmp::min(n as usize, participations.len());
    let ku8 = k;

    let mut idx: usize = 0;
    while idx < limit
        invariant
            idx <= limit,
            count as int == count_eligible(participations@.slice(0, idx as int), ku8 as int),
            k <= 5,
            forall|i: int| 0 <= i && i < participations@.len() as int ==> participations@.index(i) <= 5,
        decreases limit - idx,
    {
        let p = participations[idx];
        if 5 - (p as u8) >= ku8 {
            count = count + 1;
        }
        idx += 1;
    }

    // number of groups of 3 = count / 3 (integer division)
    count / 3
}

}
